# ==============================================================================# 093_CRM_PIPELINE_ENGINE.py## IOTEC CRM PIPELINE ENGINE## Missão:# Criar e controlar oportunidades comerciais.# ==============================================================================from __future__ import annotationsimport sqlite3import hashlibimport jsonimport uuidfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class CRMPipelineEngine:    STAGES = [        "LEAD",        "QUALIFIED",        "FIRST_CONTACT",        "DISCOVERY",        "PROPOSAL",        "NEGOTIATION",        "CONTRACT",        "CUSTOMER"    ]    VALID_TRANSITIONS = {        "LEAD": ["QUALIFIED"],        "QUALIFIED": ["FIRST_CONTACT"],        "FIRST_CONTACT": ["DISCOVERY"],        "DISCOVERY": ["PROPOSAL"],        "PROPOSAL": ["NEGOTIATION"],        "NEGOTIATION": ["CONTRACT"],        "CONTRACT": ["CUSTOMER"],        "CUSTOMER": []    }    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS commercial_pipeline(            id INTEGER PRIMARY KEY AUTOINCREMENT,            opportunity_uuid TEXT UNIQUE,            company_uuid TEXT UNIQUE,            lead_score INTEGER,            pipeline_stage TEXT,            owner TEXT,            status TEXT,            next_action TEXT,            next_action_date TEXT,            estimated_value REAL,            probability INTEGER,            created_at TEXT,            updated_at TEXT,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ------------------------------------------------------------------    def _sha(self, obj):        raw = json.dumps(            obj,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ------------------------------------------------------------------    def _probability(self, stage):        tabela = {            "LEAD": 5,            "QUALIFIED": 15,            "FIRST_CONTACT": 30,            "DISCOVERY": 45,            "PROPOSAL": 60,            "NEGOTIATION": 80,            "CONTRACT": 95,            "CUSTOMER": 100        }        return tabela.get(stage, 0)    # ------------------------------------------------------------------    def create_pipeline(self):        leads = self.conn.execute("""            SELECT *            FROM commercial_leads        """).fetchall()        criados = 0        for lead in leads:            existe = self.conn.execute("""                SELECT 1                FROM commercial_pipeline                WHERE company_uuid=?            """,(lead["company_uuid"],)).fetchone()            if existe:                continue            stage = "QUALIFIED"            payload = {                "opportunity_uuid": str(uuid.uuid4()),                "company_uuid": lead["company_uuid"],                "lead_score": lead["lead_score"],                "pipeline_stage": stage,                "owner": "UNASSIGNED",                "status": "OPEN",                "next_action": "Realizar primeiro contato",                "next_action_date": None,                "estimated_value": 0.0,                "probability": self._probability(stage),                "created_at": datetime.utcnow().isoformat(),                "updated_at": datetime.utcnow().isoformat(),                "metadata": {                    "origin":"093_CRM_PIPELINE_ENGINE"                }            }            assinatura = self._sha(payload)            self.conn.execute("""            INSERT INTO commercial_pipeline(                opportunity_uuid,                company_uuid,                lead_score,                pipeline_stage,                owner,                status,                next_action,                next_action_date,                estimated_value,                probability,                created_at,                updated_at,                metadata,                hash            )            VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)            """,(                payload["opportunity_uuid"],                payload["company_uuid"],                payload["lead_score"],                payload["pipeline_stage"],                payload["owner"],                payload["status"],                payload["next_action"],                payload["next_action_date"],                payload["estimated_value"],                payload["probability"],                payload["created_at"],                payload["updated_at"],                json.dumps(payload["metadata"],ensure_ascii=False),                assinatura            ))            criados += 1        self.conn.commit()        return criados    # ------------------------------------------------------------------    def move_stage(self, opportunity_uuid, new_stage):        atual = self.conn.execute("""            SELECT *            FROM commercial_pipeline            WHERE opportunity_uuid=?        """,(opportunity_uuid,)).fetchone()        if atual is None:            raise RuntimeError("Oportunidade não encontrada.")        atual = dict(atual)        permitido = self.VALID_TRANSITIONS.get(            atual["pipeline_stage"],            []        )        if new_stage not in permitido:            raise RuntimeError(                f"Transição inválida: "                f"{atual['pipeline_stage']} -> {new_stage}"            )        self.conn.execute("""            UPDATE commercial_pipeline            SET                pipeline_stage=?,                probability=?,                updated_at=?            WHERE opportunity_uuid=?        """,(            new_stage,            self._probability(new_stage),            datetime.utcnow().isoformat(),            opportunity_uuid        ))        self.conn.commit()# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    engine = CRMPipelineEngine()    total = engine.create_pipeline()    print("="*80)    print("CRM PIPELINE")    print("="*80)    print(f"Oportunidades criadas : {total}")    print("Status                : SUCCESS")    print("="*80)